public function import(Request $request, LoggerInterface $logger): Response
{
    try {
        $this->importer->run($request->files->get('file'));
    } catch (ImportException $e) {   // your own exception class
        $logger->warning('Import failed', ['error' => $e->getMessage()]);
        return $this->json(['status' => 'error', 'message' => $e->getMessage()], 422);
    }
    return $this->json(['status' => 'ok']);
}
